{"path": "crypto_dashboard.py", "content": "import requests, sqlite3, datetime, os, sys

DB_PATH = os.path.join(os.path.dirname(__file__), "crypto_prices.db")
API_URL = "https://api.binance.com/api/v3/ticker/24hr"
SYMBOLS = ["BTCUSDT", "ETHUSDT", "SOLUSDT"]

def fetch_prices():
    try:
        resp = requests.get(API_URL, timeout=10)
        resp.raise_for_status()
        data = resp.json()
        price_map = {}
        for item in data:
            if item["symbol"] in SYMBOLS:
                price_map[item["symbol"]] = {
                    "price": float(item["lastPrice"]),
                    "priceChangePercent": float(item["priceChangePercent"]),
                    "volume": float(item["volume"]),
                }
        return price_map
    except Exception as e:
        print(f"Error fetching prices: {e}")
        return {}

def init_db():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS price_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT NOT NULL,
            symbol TEXT NOT NULL,
            price REAL NOT NULL,
            change_percent REAL,
            volume REAL
        )
        """
    )
    conn.commit()
    conn.close()

def log_prices(price_map):
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    ts = datetime.datetime.utcnow().isoformat()
    for symbol, info in price_map.items():
        cur.execute(
            "INSERT INTO price_log (timestamp, symbol, price, change_percent, volume) VALUES (?, ?, ?, ?, ?)",
            (ts, symbol, info["price"], info["priceChangePercent"], info["volume"]),
        )
    conn.commit()
    conn.close()

def display_dashboard(price_map):
    print("""\n=== Crypto Quick Dashboard ===\n""")
    now = datetime.datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S UTC")
    print(f"Timestamp: {now}\n")
    for symbol in SYMBOLS:
        info = price_map.get(symbol)
        if not info:
            continue
        trend = "🔺" if info["priceChangePercent"] >= 0 else "🔻"
        print(f"{symbol[:3]}: ${info['price']:.2f} {trend} ({info['priceChangePercent']:+.2f}% )  Vol:{info['volume']:.0f}")
    print("\nData logged to SQLite DB (crypto_prices.db)\n")

def main():
    init_db()
    price_map = fetch_prices()
    if not price_map:
        sys.exit(1)
    log_prices(price_map)
    display_dashboard(price_map)

if __name__ == "__main__":
    main()
